command:
$ErrorActionPreference = 'Stop'
$workspaceRoot = 'D:\GitHub\Forge-Conductor-Windows-Edition'
. (Join-Path $workspaceRoot '.forge-codex\instructions\scripts\Common.ps1')
$evidenceRelative = '.forge-codex\state\evidence\P16\dashboard-operational-persistence-foundations-checkpoint.json'
$evidencePath = Join-Path $workspaceRoot $evidenceRelative
$evidence = Get-Content -Raw -LiteralPath $evidencePath | ConvertFrom-Json
$sourceProperties = @($evidence.source_sha256.PSObject.Properties)
if ($sourceProperties.Count -ne 29) { throw "Unexpected source hash count: $($sourceProperties.Count)" }
foreach ($property in $sourceProperties) {
    $actual = Get-FileSha256 -Path (Join-Path $workspaceRoot $property.Name)
    if ($actual -ne [string]$property.Value) { throw "Source hash mismatch: $($property.Name)" }
}
$binaryPaths = [ordered]@{
    'forge-conductor.exe' = 'out\build\windows-msvc-x64\bin\Release\forge-conductor.exe'
    'ForgeConductor.Contracts.HeaderSelfContainment.exe' = 'out\build\windows-msvc-x64\bin\Release\ForgeConductor.Contracts.HeaderSelfContainment.exe'
    'ForgeConductor.Application.ClientPresenceLifecycleTests.exe' = 'out\build\windows-msvc-x64\bin\Release\ForgeConductor.Application.ClientPresenceLifecycleTests.exe'
    'ForgeConductor.Persistence.ClientPresenceRepositoryWindowsTests.exe' = 'out\build\windows-msvc-x64\bin\Release\ForgeConductor.Persistence.ClientPresenceRepositoryWindowsTests.exe'
    'ForgeConductor.Persistence.ForgeStatusRepositoryWindowsTests.exe' = 'out\build\windows-msvc-x64\bin\Release\ForgeConductor.Persistence.ForgeStatusRepositoryWindowsTests.exe'
    'ForgeConductor.Persistence.UnitTests.exe' = 'out\build\windows-msvc-x64\bin\Release\ForgeConductor.Persistence.UnitTests.exe'
    'ForgeConductor.Agents.RepositoryWindowsTests.exe' = 'out\build\windows-msvc-x64\bin\Release\ForgeConductor.Agents.RepositoryWindowsTests.exe'
    'ForgeConductor.Infrastructure.DiagnosticLogTailReaderTests.exe' = 'out\build\windows-msvc-x64\bin\Release\ForgeConductor.Infrastructure.DiagnosticLogTailReaderTests.exe'
    'ForgeConductor.Persistence.DashboardOperationalRepositoryWindowsTests.exe' = 'out\build\windows-msvc-x64\bin\Release\ForgeConductor.Persistence.DashboardOperationalRepositoryWindowsTests.exe'
    'ForgeConductor.Persistence.Windows.lib' = 'out\build\windows-msvc-x64\lib\Release\ForgeConductor.Persistence.Windows.lib'
    'ForgeConductor.Infrastructure.Windows.lib' = 'out\build\windows-msvc-x64\lib\Release\ForgeConductor.Infrastructure.Windows.lib'
    'ForgeConductor.Application.lib' = 'out\build\windows-msvc-x64\lib\Release\ForgeConductor.Application.lib'
}
foreach ($entry in $binaryPaths.GetEnumerator()) {
    $actual = Get-FileSha256 -Path (Join-Path $workspaceRoot $entry.Value)
    if ($actual -ne [string]$evidence.binary_sha256.($entry.Key)) { throw "Binary hash mismatch: $($entry.Key)" }
}
$commandRecords = @(
    @('.forge-codex\state\commands\20260830T113133885Z-6fb8e63a.json', [string]$evidence.recorded_build.command_record_sha256),
    @('.forge-codex\state\commands\20260830T113326030Z-c898b0b4.json', [string]$evidence.recorded_validation.command_record_sha256)
)
foreach ($record in $commandRecords) {
    if ((Get-FileSha256 -Path (Join-Path $workspaceRoot $record[0])) -ne $record[1]) { throw "Command-record hash mismatch: $($record[0])" }
}
$testRecord = Get-Content -Raw -LiteralPath (Join-Path $workspaceRoot $commandRecords[1][0]) | ConvertFrom-Json
if ([string]$testRecord.command -match '(-L|--label-regex)\s+G16') { throw 'Focused validation invoked the G16 label gate.' }
$testStdout = Get-Content -Raw -LiteralPath (Join-Path $workspaceRoot $testRecord.stdout)
if ($testStdout -notmatch '100% tests passed out of 8') { throw 'Focused validation did not report eight passing tests.' }
$buildRecord = Get-Content -Raw -LiteralPath (Join-Path $workspaceRoot $commandRecords[0][0]) | ConvertFrom-Json
if ([string]$buildRecord.command -match '(-L|--label-regex)\s+G16') { throw 'Focused build invoked the G16 label gate.' }
$runState = Get-Content -Raw -LiteralPath (Join-Path $workspaceRoot '.forge-codex\state\run-state.json') | ConvertFrom-Json
$p16 = @($runState.phases | Where-Object id -eq 'P16')
$g16 = @($runState.gates | Where-Object id -eq 'G16')
if ($p16.Count -ne 1 -or $p16[0].status -ne 'in_progress') { throw 'P16 durable state is not in_progress.' }
if ($g16.Count -ne 1 -or $g16[0].status -ne 'not_started') { throw 'G16 durable state is not not_started.' }
if ($p16[0].evidence -notcontains $evidenceRelative.Replace('\','/')) { throw 'P16 durable state omits this checkpoint.' }
$migrationSource = [IO.File]::ReadAllText((Join-Path $workspaceRoot 'src\Persistence\Windows\Migrations\CentralMigrations.cpp')).Replace(([string][char]13 + [char]10), [string][char]10)
$migrationMatch = [regex]::Match($migrationSource, 'constexpr std::string_view C007Sql = R"sql\((?<sql>.*?)\)sql";', [Text.RegularExpressions.RegexOptions]::Singleline)
if (-not $migrationMatch.Success) { throw 'C007 SQL literal was not found.' }
$migrationHash = Get-StringSha256 -Value $migrationMatch.Groups['sql'].Value
if ($migrationHash -ne [string]$evidence.measured_results.central_migration_007_sha256) { throw 'C007 SQL checksum mismatch.' }
& (Join-Path $workspaceRoot '.forge-codex\instructions\scripts\Validate-NoPython.ps1') -WorkspaceRoot $workspaceRoot
& (Join-Path $workspaceRoot '.forge-codex\instructions\scripts\Validate-NoAttribution.ps1') -WorkspaceRoot $workspaceRoot
& (Join-Path $workspaceRoot '.forge-codex\instructions\scripts\Verify-Ledger.ps1') -WorkspaceRoot $workspaceRoot
$diffOutput = & git -C $workspaceRoot diff --check 2>&1
if ($LASTEXITCODE -ne 0) { throw "git diff --check failed: $diffOutput" }
$changedTextFiles = @($sourceProperties.Name) + $evidenceRelative
$strictUtf8 = New-Object Text.UTF8Encoding($false, $true)
foreach ($relative in $changedTextFiles) {
    $bytes = [IO.File]::ReadAllBytes((Join-Path $workspaceRoot $relative))
    if ($bytes.Length -ge 3 -and $bytes[0] -eq 0xef -and $bytes[1] -eq 0xbb -and $bytes[2] -eq 0xbf) { throw "UTF-8 BOM is forbidden: $relative" }
    $text = $strictUtf8.GetString($bytes)
    if ($text -match '(?<!\r)\n' -or $text -match '\r(?!\n)') { throw "Non-CRLF line ending: $relative" }
    foreach ($line in [regex]::Split($text, '\r\n')) { if ($line -match '[ \t]+$') { throw "Trailing whitespace: $relative" } }
}
Write-Output "Source hashes matched: $($sourceProperties.Count)"
Write-Output "Binary hashes matched: $($binaryPaths.Count)"
Write-Output "Command records matched: $($commandRecords.Count)"
Write-Output "Changed text files CRLF UTF-8 no BOM: $($changedTextFiles.Count)"
Write-Output "C007 checksum matched: $migrationHash"
Write-Output 'Focused selection did not invoke the G16 label gate.'
Write-Output 'P16 in_progress and G16 not_started durable state verified.'
Write-Output 'git diff --check passed.'
exit 0
